parameters.jsCode:
const b = $json.body || {};
const out = { name: b.name, email: b.email, teamEmails: b.teamEmails || '', company: b.company, site: b.site || '', social: b.social || '', industry: b.industry || '', painPoint: b.painPoint || '', audioSeconds: b.audioSeconds || 0, hasAudio: !!b.audioBase64 };
if (b.audioBase64) {
  const mime = b.audioMime || 'audio/webm';
  const ext = mime.includes('wav') ? 'wav' : mime.includes('mp4') ? 'm4a' : mime.includes('ogg') ? 'ogg' : 'webm';
  const bin = await this.helpers.prepareBinaryData(Buffer.from(b.audioBase64, 'base64'), 'pain-point-voice-note.' + ext, mime);
  return { json: out, binary: { voiceNote: bin } };
}
return { json: out };

